const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const root = '/data/research-alerts';
const statePath = path.join(root, 'n8n_error_alert_state.json');
const outboxDir = path.join(root, 'muse-alerts');
fs.mkdirSync(outboxDir, { recursive: true });

const exec = $input.first().json || {};
const wf = exec.workflow || {};
const execInfo = exec.execution || {};
const err = execInfo.error || exec.error || {};
const workflowId = String(wf.id || exec.workflowId || 'unknown');
const workflowName = String(wf.name || workflowId);
const nodeName = String((err.node || {}).name || err.node || 'unknown');
const message = String(err.message || 'n8n execution failed').slice(0, 500);
const executionId = String(execInfo.id || exec.id || '');
const fingerprint = crypto
  .createHash('sha256')
  .update([workflowId, nodeName, message].join('|'))
  .digest('hex')
  .slice(0, 24);

let state = { alerts: {} };
try {
  if (fs.existsSync(statePath)) {
    state = JSON.parse(fs.readFileSync(statePath, 'utf8')) || { alerts: {} };
  }
} catch (e) {
  state = { alerts: {} };
}
state.alerts = state.alerts || {};

const now = Date.now();
const windowMs = 30 * 60 * 1000;
const prev = state.alerts[fingerprint];
const suppress = !!(prev && (now - Number(prev.ts || 0)) < windowMs);

const payload = {
  kind: 'n8n_error',
  fingerprint,
  suppress,
  checked_at: new Date(now).toISOString(),
  workflow_id: workflowId,
  workflow_name: workflowName,
  node: nodeName,
  message,
  execution_id: executionId,
  muse_route: 'monitor_gateway_poll',
};

state.alerts[fingerprint] = {
  ts: now,
  count: Number((prev && prev.count) || 0) + 1,
  last_execution_id: executionId,
  suppress,
};
// prune old fingerprints (>24h)
for (const [k, v] of Object.entries(state.alerts)) {
  if (now - Number(v.ts || 0) > 24 * 60 * 60 * 1000) delete state.alerts[k];
}
fs.writeFileSync(statePath, JSON.stringify(state, null, 2));
fs.writeFileSync(path.join(outboxDir, 'latest_error.json'), JSON.stringify(payload, null, 2));
if (!suppress) {
  fs.writeFileSync(
    path.join(outboxDir, `error-${fingerprint}-${executionId || now}.json`),
    JSON.stringify(payload, null, 2)
  );
}

return [{ json: payload }];
